# =============================================================================
# 维表映射配置（由 generate_dimension_map_from_schema.py 根据 ERP 表结构 V1.0 生成）
# 与 MES 维表映射（mes_dimension_joins.map）分离维护，勿混用 TBL_* / CID 等 MES 约定
# 改完后运行：python3 build_dify_bundle.py → 复制 dify_erp_dimension_node.py 到 Dify
# =============================================================================
#
# 写法说明：
#   [表 表名]           一张 ERP 业务主表（外键多为 *Id → 维表.recId）
#   标签=               中文说明
#   关键词=             用户问题里出现这些词时，选中该表（逗号分隔）
#   别名=               SQL 里事实表别名
#
#   [映射 英文名]       一组「事实字段 → 维表 → 中文列」
#   字段=               事实表上的列，多个用逗号分隔
#   类型=枚举           状态/类型等码值字段，SELECT 须用 CASE 译码
#   关联=别名 | 维表 | ON条件
#   列=SQL表达式 | 中文列名
#   展示列=表达式 | 中文列名
#   禁止=               不要这样写 SQL
#
# [全局] 下「禁止=」对所有表生效

[全局]
默认别名=fr
禁止=FROM/JOIN 表名与 WITH (NOLOCK) 拆成两行
禁止=无时间条件的明细列表查询省略 ORDER BY（须按主时间列 DESC 由近到远）
禁止=使用 MES 表名/字段（TBL_*、CID、CWC_ID 等）解析 ERP 业务
禁止=FGI_IQCResult/FGI_IQCItem/FGI_IQCHistory/FGI_IQCWF/P_WO 等表无 modifiedBy 列，禁止写 事实表.modifiedBy
禁止=有 modifiedBy 的表其为字符串用户名，禁止 JOIN T_User ON recId = 事实表.modifiedBy；修改人直接用 事实表.modifiedBy AS [修改人]

[表 FGI_Receipt]
标签=制成品接收单
关键词=制成品接收, 接收单, FGI_Receipt
别名=fr

[映射 type]
字段=type
类型=枚举
说明=状态码译码：Customer：客户 Outsourcing：供应商
列=CASE UPPER(RTRIM(fr.type)) WHEN 'CUSTOMER' THEN N'客户' WHEN 'OUTSOURCING' THEN N'供应商' ELSE fr.type END | 来源类型
禁止=fr.type AS [来源类型]

[映射 creator]
字段=creatorId
关联=tu | T_User | tu.recId = fr.creatorId
列=tu.employeeName | 创建人名称
列=tu.loginName | 创建人账号
列=tu.userCode | 创建人代码
禁止=fr.creatorId AS [创建人名称]

[映射 plants]
字段=plantsId
关联=tp | T_Plants | tp.recId = fr.plantsId
列=tp.name | 工厂名称
列=tp.code | 工厂代码
列=CASE UPPER(RTRIM(tp.ifPanelBOtherMI)) WHEN 'AB' THEN N'板允许' WHEN 'B' THEN N'板换料号' ELSE tp.ifPanelBOtherMI END | ifPanelBOtherMI

[映射 post_role]
字段=postRoleId
关联=tpostr | T_PostRole | tpostr.recId = fr.postRoleId
列=tpostr.name | 岗位名称
列=tpostr.code | 岗位代码
列=CASE UPPER(RTRIM(tpostr.type)) WHEN 'GENERAL' THEN N'一般类型' WHEN 'MI' THEN N'工程设计' ELSE tpostr.type END | 岗位类型

[映射 source_to_suppliers]
字段=sourceId
关联=msuppl | M_Suppliers | msuppl.recId = fr.sourceId
列=msuppl.name | 供应商名称
列=msuppl.code | 供应商代码
列=CASE WHEN (UPPER(RTRIM(CAST(msuppl.ifActive AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(msuppl.ifActive AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(msuppl.ifActive AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(msuppl.ifActive AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(msuppl.ifActive AS NVARCHAR(20)) END | 是否激活
列=CASE WHEN (UPPER(RTRIM(CAST(msuppl.ifConsignment AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(msuppl.ifConsignment AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(msuppl.ifConsignment AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(msuppl.ifConsignment AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(msuppl.ifConsignment AS NVARCHAR(20)) END | 是否寄售
列=CASE WHEN (UPPER(RTRIM(CAST(msuppl.ifForeign AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(msuppl.ifForeign AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(msuppl.ifForeign AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(msuppl.ifForeign AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(msuppl.ifForeign AS NVARCHAR(20)) END | 是否国外采购商
列=CASE WHEN (UPPER(RTRIM(CAST(msuppl.ifReactionary AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(msuppl.ifReactionary AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(msuppl.ifReactionary AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(msuppl.ifReactionary AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(msuppl.ifReactionary AS NVARCHAR(20)) END | 是否外协
列=CASE WHEN (UPPER(RTRIM(CAST(msuppl.ifReconcile AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(msuppl.ifReconcile AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(msuppl.ifReconcile AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(msuppl.ifReconcile AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(msuppl.ifReconcile AS NVARCHAR(20)) END | 是否对账
列=CASE UPPER(RTRIM(msuppl.status)) WHEN 'VALID' THEN N'审批通过' ELSE msuppl.status END | 状态

[映射 source_to_customer]
字段=sourceId
关联=scusto | S_Customer | scusto.recId = fr.sourceId
列=scusto.name | 客户名称
列=scusto.code | 客户代码
列=CASE WHEN (UPPER(RTRIM(CAST(scusto.applyInTransit AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(scusto.applyInTransit AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(scusto.applyInTransit AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(scusto.applyInTransit AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(scusto.applyInTransit AS NVARCHAR(20)) END | 在库存中使用；0: 否

展示列=fr.code | 接收单号
展示列=fr.customsCode | 海关单号
展示列=fr.deliveryCode | 送货单号
展示列=fr.entDate | 创建日期
展示列=fr.locked | -
展示列=fr.note | -
展示列=fr.receiveDate | 收货日期
展示列=fr.sourceCode | 供应商/客户  代码
展示列=fr.version | -
展示列=fr.EnterDate | 接收时间

[表 FGI_ReceiptItem]
标签=制成品接收单明细
关键词=制成品接收明细, 接收明细, FGI_ReceiptItem
别名=fri

[映射 ifinspection]
字段=ifInspection
类型=枚举
说明=枚举译码：是否要检查 0否 1是
列=CASE WHEN (UPPER(RTRIM(CAST(fri.ifInspection AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(fri.ifInspection AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(fri.ifInspection AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(fri.ifInspection AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(fri.ifInspection AS NVARCHAR(20)) END | 是否要检查
禁止=fri.ifInspection AS [是否要检查]

[映射 ordertype]
字段=orderType
类型=枚举
说明=状态码译码：Outsourcing：供应商，Exchange客户
列=CASE UPPER(RTRIM(fri.orderType)) WHEN 'OUTSOURCING' THEN N'供应商' WHEN 'EXCHANGE' THEN N'客户' ELSE fri.orderType END | 订单类型
禁止=fri.orderType AS [订单类型]

[映射 wotype]
字段=woType
类型=枚举
说明=状态码译码：加工状态：Working：已加工  UnWorking：未加工
列=CASE UPPER(RTRIM(fri.woType)) WHEN 'WORKING' THEN N'已加工' WHEN 'UNWORKING' THEN N'未加工' ELSE fri.woType END | 加工状态
禁止=fri.woType AS [加工状态]

[映射 fgireceipt_to_receipt]
字段=fgiReceiptId
关联=fgirec | FGI_Receipt | fgirec.recId = fri.fgiReceiptId
列=fgirec.code | 接收单号
列=CASE UPPER(RTRIM(fgirec.type)) WHEN 'CUSTOMER' THEN N'客户' WHEN 'OUTSOURCING' THEN N'供应商' ELSE fgirec.type END | 来源类型

[映射 job]
字段=jobId
关联=sj | S_Job | sj.recId = fri.jobId
列=sj.partNum | 产品编码
列=sj.partName | 部件名称
列=CASE WHEN (UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) = N'活动') THEN N'活动' WHEN (UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) = N'取消') THEN N'取消' ELSE CAST(sj.inActive AS NVARCHAR(20)) END | 停止使用；0: 活动
列=CASE UPPER(RTRIM(sj.jobStatus)) WHEN 'MI' THEN N'状态' ELSE sj.jobStatus END | jobStatus
列=CASE WHEN (UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.planOnhold AS NVARCHAR(20)) END | 计划暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.releaseOnhold AS NVARCHAR(20)) END | 发放暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.soOnhold AS NVARCHAR(20)) END | 销售暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.halogenFree AS NVARCHAR(20)) END | 无卤素；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.preQualify AS NVARCHAR(20)) END | 是否预审单；0: 否

[映射 post_role]
字段=postRoleId
关联=tpostr | T_PostRole | tpostr.recId = fri.postRoleId
列=tpostr.name | 岗位名称
列=tpostr.code | 岗位代码
列=CASE UPPER(RTRIM(tpostr.type)) WHEN 'GENERAL' THEN N'一般类型' WHEN 'MI' THEN N'工程设计' ELSE tpostr.type END | 岗位类型

[映射 salespart_to_salesparts]
字段=salesPartId
关联=ssales | S_SalesParts | ssales.recId = fri.salesPartId
列=ssales.ifCreateJob | 是否生成同名生产编号
列=ssales.endCustPartNum | 终端产品编号
列=ssales.endCustPartDesc | 终端产品名称
列=ssales.routs | -
列=CASE UPPER(RTRIM(ssales.type)) WHEN 'SAMPLE' THEN N'样板' WHEN 'BATCH' THEN N'批量' WHEN 'OTHER' THEN N'其它' WHEN 'MGSUIT' THEN N'套版主板' WHEN 'SUBSUIT' THEN N'套版子板' WHEN 'MGSUITSAMPLE' THEN N'套板主板样板' WHEN 'SEMIFINISHED' THEN N'半自制' WHEN 'SUBSUITSAMPLE' THEN N'套板子版样版' ELSE ssales.type END | 类型
列=CASE WHEN (UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) = N'有卤') THEN N'有卤' WHEN (UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) = N'无卤素') THEN N'无卤素' ELSE CAST(ssales.halogenFree AS NVARCHAR(20)) END | 0有卤
列=CASE WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'建档中') THEN N'建档中' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'待MI') THEN N'待MI' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'2') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'MI制作中') THEN N'MI制作中' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'3') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'退回建档') THEN N'退回建档' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'4') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'已完成。') THEN N'已完成。' ELSE CAST(ssales.archiveStatus AS NVARCHAR(20)) END | archiveStatus

