[表 M_Materials]
标签=物料表
关键词=物料, 材料, M_Materials
别名=mat

[映射 botcu_to_conductor]
字段=botCuId
关联=scondu | S_Conductor | scondu.recId = mat.botCuId
列=scondu.code | 代码
列=scondu.sort | -
列=scondu.forLayer | 是否用于铜层
列=scondu.forCoreCu | 是否用于覆铜板

[映射 buyunit_to_unit]
字段=buyUnitId
关联=tunit | T_Unit | tunit.recId = mat.buyUnitId
列=tunit.name | 单位名称
列=tunit.code | 单位代码

[映射 company]
字段=companyId
关联=tc | T_Company | tc.recId = mat.companyId
列=tc.name | 公司名称
列=tc.code | 公司代码
列=CASE UPPER(RTRIM(tc.postType)) WHEN 'M' THEN N'月度' WHEN 'Y' THEN N'年度' ELSE tc.postType END | 结账方式
列=CASE UPPER(RTRIM(tc.prodType)) WHEN 'SELF' THEN N'自制' WHEN 'INTERNAL' THEN N'内部外发' WHEN 'OUTSOURCING' THEN N'外部外发' ELSE tc.prodType END | 加工方式
列=CASE UPPER(RTRIM(tc.spdsPriceConsignMat)) WHEN 'PO' THEN N'从' WHEN 'SPDS' THEN N'取价' ELSE tc.spdsPriceConsignMat END | spdsPriceConsignMat
列=CASE UPPER(RTRIM(tc.ifMulMICoding)) WHEN 'MI' THEN N'编码' ELSE tc.ifMulMICoding END | ifMulMICoding

[映射 creator]
字段=creatorId
关联=tu | T_User | tu.recId = mat.creatorId
列=tu.employeeName | 创建人名称
列=tu.loginName | 创建人账号
列=tu.userCode | 创建人代码
禁止=mat.creatorId AS [创建人名称]

[映射 customsunit_to_unit]
