[映射 pd_to_materialtype]
字段=pdId
关联=smater | S_MaterialType | smater.recId = mat.pdId
列=smater.matTypeCode | 类型代码
列=smater.matTypeName | 名称
列=smater.isFilm | isFilm
列=CASE WHEN (UPPER(RTRIM(CAST(smater.ifRigid AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(smater.ifRigid AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(smater.ifRigid AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(smater.ifRigid AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(smater.ifRigid AS NVARCHAR(20)) END | 是否用于硬板
列=CASE WHEN (UPPER(RTRIM(CAST(smater.ifFlex AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(smater.ifFlex AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(smater.ifFlex AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(smater.ifFlex AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(smater.ifFlex AS NVARCHAR(20)) END | 是否用于软板
列=CASE WHEN (UPPER(RTRIM(CAST(smater.ifMfgPart AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(smater.ifMfgPart AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(smater.ifMfgPart AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(smater.ifMfgPart AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(smater.ifMfgPart AS NVARCHAR(20)) END | 是否用于制造部件
列=CASE WHEN (UPPER(RTRIM(CAST(smater.ifBOMIssue AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(smater.ifBOMIssue AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(smater.ifBOMIssue AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(smater.ifBOMIssue AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(smater.ifBOMIssue AS NVARCHAR(20)) END | ifBOMIssue
列=CASE WHEN (UPPER(RTRIM(CAST(smater.ifLackMatCheck AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(smater.ifLackMatCheck AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(smater.ifLackMatCheck AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(smater.ifLackMatCheck AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(smater.ifLackMatCheck AS NVARCHAR(20)) END | 是否用于欠料检查

