[表 M_InventoryBatch]
标签=物料批次库存
关键词=物料批次, 批次库存, InventoryBatch
别名=ib

[映射 consignmentflg]
字段=consignmentFlg
类型=枚举
说明=枚举译码：是否寄售；0.否   1是
列=CASE WHEN (UPPER(RTRIM(CAST(ib.consignmentFlg AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ib.consignmentFlg AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ib.consignmentFlg AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ib.consignmentFlg AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ib.consignmentFlg AS NVARCHAR(20)) END | 是否寄售
禁止=ib.consignmentFlg AS [是否寄售]

[映射 taxfree]
字段=taxFree
类型=枚举
说明=枚举译码：是否外购库存；0.否  1.是
列=CASE WHEN (UPPER(RTRIM(CAST(ib.taxFree AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ib.taxFree AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ib.taxFree AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ib.taxFree AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ib.taxFree AS NVARCHAR(20)) END | 是否外购库存；0.否
禁止=ib.taxFree AS [是否外购库存；0.否]

[映射 remaining]
字段=remaining
类型=枚举
说明=枚举译码：碎料；0.否  1.是
列=CASE WHEN (UPPER(RTRIM(CAST(ib.remaining AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ib.remaining AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ib.remaining AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ib.remaining AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ib.remaining AS NVARCHAR(20)) END | 碎料；0.否
禁止=ib.remaining AS [碎料；0.否]

