标签=产品型号  生产部件
关键词=产品型号, 生产部件, S_Job
别名=job

[映射 inactive]
字段=inActive
类型=枚举
说明=枚举译码：停止使用；0: 活动; 1: 取消
列=CASE WHEN (UPPER(RTRIM(CAST(job.inActive AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(job.inActive AS NVARCHAR(20)))) = N'活动') THEN N'活动' WHEN (UPPER(RTRIM(CAST(job.inActive AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(job.inActive AS NVARCHAR(20)))) = N'取消') THEN N'取消' ELSE CAST(job.inActive AS NVARCHAR(20)) END | 停止使用；0: 活动
禁止=job.inActive AS [停止使用；0: 活动]

[映射 jobstatus]
字段=jobStatus
类型=枚举
说明=状态码译码：MI 状态
列=CASE UPPER(RTRIM(job.jobStatus)) WHEN 'MI' THEN N'状态' ELSE job.jobStatus END | jobStatus
禁止=job.jobStatus AS [jobStatus]

[映射 planonhold]
字段=planOnhold
类型=枚举
说明=枚举译码：计划暂停；0: 否; 1: 是
列=CASE WHEN (UPPER(RTRIM(CAST(job.planOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(job.planOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(job.planOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(job.planOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(job.planOnhold AS NVARCHAR(20)) END | 计划暂停；0: 否
禁止=job.planOnhold AS [计划暂停；0: 否]

[映射 releaseonhold]
字段=releaseOnhold
类型=枚举
说明=枚举译码：发放暂停；0: 否; 1: 是
列=CASE WHEN (UPPER(RTRIM(CAST(job.releaseOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(job.releaseOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(job.releaseOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(job.releaseOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(job.releaseOnhold AS NVARCHAR(20)) END | 发放暂停；0: 否
禁止=job.releaseOnhold AS [发放暂停；0: 否]

[映射 soonhold]
字段=soOnhold
类型=枚举
说明=枚举译码：销售暂停；0: 否; 1: 是
列=CASE WHEN (UPPER(RTRIM(CAST(job.soOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(job.soOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(job.soOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(job.soOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(job.soOnhold AS NVARCHAR(20)) END | 销售暂停；0: 否
禁止=job.soOnhold AS [销售暂停；0: 否]

[映射 halogenfree]
字段=halogenFree
类型=枚举
说明=枚举译码：无卤素；0: 否; 1: 是
列=CASE WHEN (UPPER(RTRIM(CAST(job.halogenFree AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(job.halogenFree AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(job.halogenFree AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(job.halogenFree AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(job.halogenFree AS NVARCHAR(20)) END | 无卤素；0: 否
禁止=job.halogenFree AS [无卤素；0: 否]

[映射 prequalify]
字段=preQualify
类型=枚举
说明=枚举译码：是否预审单；0: 否; 1: 是
列=CASE WHEN (UPPER(RTRIM(CAST(job.preQualify AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(job.preQualify AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(job.preQualify AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(job.preQualify AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(job.preQualify AS NVARCHAR(20)) END | 是否预审单；0: 否
禁止=job.preQualify AS [是否预审单；0: 否]

