[映射 sale_type]
字段=saleType
类型=枚举
说明=状态码译码：销售类型：Bonded 保税 ForDomestic 内销 ForExport 外销
列=CASE UPPER(RTRIM(mo.saleType)) WHEN 'BONDED' THEN N'保税' WHEN 'FORDOMESTIC' THEN N'内销' WHEN 'FOREXPORT' THEN N'外销' ELSE mo.saleType END | 销售类型
禁止=mo.saleType AS [销售类型]

[映射 status]
字段=status
类型=枚举
说明=枚举译码：单据状态：Active 激活  Order 已下单；（1外协 WOWX; 2未发放 WOWFF; 3已发放 WOYFF; 4暂停 WOZT; 5取消 WOQX;
列=CASE UPPER(RTRIM(mo.status)) WHEN 'ACTIVE' THEN N'激活' WHEN 'ORDER' THEN N'已下单' WHEN 'WOWX' THEN N'外协' WHEN 'WOWFF' THEN N'未发放' WHEN 'WOYFF' THEN N'已发放' WHEN 'WOZT' THEN N'暂停' WHEN 'WOQX' THEN N'取消' WHEN 'WOWC' THEN N'完成' ELSE mo.status END | 单据状态
禁止=mo.status AS [单据状态]

[映射 synchro]
字段=synchro
类型=枚举
说明=枚举译码：同步状态，0-未同步；1-已同步；2-不同步
列=CASE UPPER(RTRIM(mo.synchro)) WHEN '0' THEN N'-未同步' WHEN '1' THEN N'-已同步' WHEN '2' THEN N'-不同步' ELSE mo.synchro END | 同步状态
禁止=mo.synchro AS [同步状态]

[映射 dev]
字段=dev
类型=枚举
说明=枚举译码：研发标识，1是，0否
