[表 A_Title]
标签=A_Title
关键词=A_Title
别名=atit

[映射 taxesflag]
字段=taxesFlag
类型=枚举
说明=状态码译码：保税类型 - Bonded: 保税; Taxes: 课税
列=CASE UPPER(RTRIM(atit.taxesFlag)) WHEN 'BONDED' THEN N'保税' WHEN 'TAXES' THEN N'课税' ELSE atit.taxesFlag END | 保税类型
禁止=atit.taxesFlag AS [保税类型]

[映射 synchro]
字段=synchro
类型=枚举
说明=枚举译码：同步状态，0-未同步；1-已同步；2-不同步
列=CASE WHEN (UPPER(RTRIM(CAST(atit.synchro AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(atit.synchro AS NVARCHAR(20)))) = N'-未同步') THEN N'-未同步' WHEN (UPPER(RTRIM(CAST(atit.synchro AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(atit.synchro AS NVARCHAR(20)))) = N'-已同步') THEN N'-已同步' WHEN (UPPER(RTRIM(CAST(atit.synchro AS NVARCHAR(20)))) IN (N'2') OR UPPER(RTRIM(CAST(atit.synchro AS NVARCHAR(20)))) = N'-不同步') THEN N'-不同步' ELSE CAST(atit.synchro AS NVARCHAR(20)) END | 同步状态
禁止=atit.synchro AS [同步状态]

[映射 wonumber]
字段=woNumber
类型=枚举
说明=状态码译码：工单号P_WO.woNumber 开头 RR  退货返修 RW：仓库返修
列=CASE UPPER(RTRIM(atit.woNumber)) WHEN 'WONUMBER' THEN N'开头' WHEN 'RR' THEN N'退货返修' ELSE atit.woNumber END | woNumber
禁止=atit.woNumber AS [woNumber]

[映射 job_to_job]
字段=JobId
关联=sjob | S_Job | sjob.recId = atit.JobId
列=sjob.partNum | 产品编码
列=sjob.partName | 部件名称
列=CASE WHEN (UPPER(RTRIM(CAST(sjob.inActive AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(sjob.inActive AS NVARCHAR(20)))) = N'活动') THEN N'活动' WHEN (UPPER(RTRIM(CAST(sjob.inActive AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(sjob.inActive AS NVARCHAR(20)))) = N'取消') THEN N'取消' ELSE CAST(sjob.inActive AS NVARCHAR(20)) END | 停止使用；0: 活动
列=CASE UPPER(RTRIM(sjob.jobStatus)) WHEN 'MI' THEN N'状态' ELSE sjob.jobStatus END | jobStatus
列=CASE WHEN (UPPER(RTRIM(CAST(sjob.planOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sjob.planOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sjob.planOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sjob.planOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sjob.planOnhold AS NVARCHAR(20)) END | 计划暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sjob.releaseOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sjob.releaseOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sjob.releaseOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sjob.releaseOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sjob.releaseOnhold AS NVARCHAR(20)) END | 发放暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sjob.soOnhold AS NVARCHAR(20)) END | 销售暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sjob.halogenFree AS NVARCHAR(20)) END | 无卤素；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sjob.preQualify AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sjob.preQualify AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sjob.preQualify AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sjob.preQualify AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sjob.preQualify AS NVARCHAR(20)) END | 是否预审单；0: 否

