[表 FGI_IQC]
标签=制成品检验单
关键词=制成品检验单
别名=fiqc

[映射 ifoutput]
字段=ifOutPut
类型=枚举
说明=枚举译码：合格入库状态 0.禁用 1.启用
列=CASE WHEN (UPPER(RTRIM(CAST(fiqc.ifOutPut AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(fiqc.ifOutPut AS NVARCHAR(20)))) = N'禁用') THEN N'禁用' WHEN (UPPER(RTRIM(CAST(fiqc.ifOutPut AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(fiqc.ifOutPut AS NVARCHAR(20)))) = N'启用') THEN N'启用' ELSE CAST(fiqc.ifOutPut AS NVARCHAR(20)) END | 合格入库状态
禁止=fiqc.ifOutPut AS [合格入库状态]

[映射 ifstock]
字段=ifStock
类型=枚举
说明=枚举译码：入库状态0.未入库   1.已入库
列=CASE WHEN (UPPER(RTRIM(CAST(fiqc.ifStock AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(fiqc.ifStock AS NVARCHAR(20)))) = N'.未入库   1.已入库') THEN N'.未入库   1.已入库' ELSE CAST(fiqc.ifStock AS NVARCHAR(20)) END | 入库状态
禁止=fiqc.ifStock AS [入库状态]

[映射 status]
字段=status
类型=枚举
说明=状态码译码：单据状态;Valid 生效
列=CASE UPPER(RTRIM(fiqc.status)) WHEN 'VALID' THEN N'生效' ELSE fiqc.status END | 单据状态
禁止=fiqc.status AS [单据状态]

[映射 type]
字段=type
类型=枚举
说明=状态码译码：类型：Outsource外协 Stock：仓库 Receipt：客诉
列=CASE UPPER(RTRIM(fiqc.type)) WHEN 'STOCK' THEN N'仓库' WHEN 'RECEIPT' THEN N'客诉' ELSE fiqc.type END | 类型
禁止=fiqc.type AS [类型]

[映射 wotype]
字段=woType
类型=枚举
说明=状态码译码：工单状态：UnWorking未加工  Working  已加工
列=CASE UPPER(RTRIM(fiqc.woType)) WHEN 'UNWORKING' THEN N'未加工' WHEN 'WORKING' THEN N'已加工' ELSE fiqc.woType END | 工单状态
禁止=fiqc.woType AS [工单状态]

