[映射 job]
字段=jobId
关联=sj | S_Job | sj.recId = fmon.jobId
列=sj.partNum | 产品编码
列=sj.partName | 部件名称
列=CASE WHEN (UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) = N'活动') THEN N'活动' WHEN (UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(sj.inActive AS NVARCHAR(20)))) = N'取消') THEN N'取消' ELSE CAST(sj.inActive AS NVARCHAR(20)) END | 停止使用；0: 活动
列=CASE UPPER(RTRIM(sj.jobStatus)) WHEN 'MI' THEN N'状态' ELSE sj.jobStatus END | jobStatus
列=CASE WHEN (UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.planOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.planOnhold AS NVARCHAR(20)) END | 计划暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.releaseOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.releaseOnhold AS NVARCHAR(20)) END | 发放暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.soOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.soOnhold AS NVARCHAR(20)) END | 销售暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.halogenFree AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.halogenFree AS NVARCHAR(20)) END | 无卤素；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sj.preQualify AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sj.preQualify AS NVARCHAR(20)) END | 是否预审单；0: 否

