[表 FGI_PackingSlip]
标签=成品出货
关键词=成品出货
别名=fpac

[映射 ifassign]
字段=ifassign
类型=枚举
说明=枚举译码：是否已做库存分配：0未做 1已做
列=CASE WHEN (UPPER(RTRIM(CAST(fpac.ifassign AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(fpac.ifassign AS NVARCHAR(20)))) = N'未做') THEN N'未做' WHEN (UPPER(RTRIM(CAST(fpac.ifassign AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(fpac.ifassign AS NVARCHAR(20)))) = N'已做') THEN N'已做' ELSE CAST(fpac.ifassign AS NVARCHAR(20)) END | 是否已做库存分配
禁止=fpac.ifassign AS [是否已做库存分配]

[映射 status]
字段=status
类型=枚举
说明=状态码译码：Action :有效   Cancel :取消         Valid：生效
列=CASE UPPER(RTRIM(fpac.status)) WHEN 'ACTION' THEN N'有效' WHEN 'CANCEL' THEN N'取消' WHEN 'VALID' THEN N'生效' ELSE fpac.status END | 状态
禁止=fpac.status AS [状态]

[映射 type]
字段=type
类型=枚举
说明=状态码译码：类型:PackingList 装箱单  DeliveryPlan:出货计划 CTransferWarehouse：寄售转仓
列=CASE UPPER(RTRIM(fpac.type)) WHEN 'DELIVERYPLAN' THEN N'出货计划' WHEN 'CTRANSFERWAREHOUSE' THEN N'寄售转仓' ELSE fpac.type END | 类型
禁止=fpac.type AS [类型]

[映射 sale_type]
字段=saleType
类型=枚举
说明=状态码译码：ForExport :一般贸易，ForDomestic：内销，Bonded：保税
列=CASE UPPER(RTRIM(fpac.saleType)) WHEN 'FOREXPORT' THEN N'一般贸易' WHEN 'FORDOMESTIC' THEN N'内销' WHEN 'BONDED' THEN N'保税' ELSE fpac.saleType END | 销售类型
禁止=fpac.saleType AS [销售类型]

