列=CASE UPPER(RTRIM(fgipac.type)) WHEN 'DELIVERYPLAN' THEN N'出货计划' WHEN 'CTRANSFERWAREHOUSE' THEN N'寄售转仓' ELSE fgipac.type END | 类型
