[映射 mo]
字段=moId
关联=pmo | P_MO | pmo.recId = fsto.moId
列=pmo.moNumber | 制造订单号
列=CASE UPPER(RTRIM(pmo.saleType)) WHEN 'BONDED' THEN N'保税' WHEN 'FORDOMESTIC' THEN N'内销' WHEN 'FOREXPORT' THEN N'外销' ELSE pmo.saleType END | 销售类型
列=CASE UPPER(RTRIM(pmo.status)) WHEN 'ACTIVE' THEN N'激活' WHEN 'ORDER' THEN N'已下单' WHEN 'WOWX' THEN N'外协' WHEN 'WOWFF' THEN N'未发放' WHEN 'WOYFF' THEN N'已发放' WHEN 'WOZT' THEN N'暂停' WHEN 'WOQX' THEN N'取消' WHEN 'WOWC' THEN N'完成' ELSE pmo.status END | 单据状态
列=CASE UPPER(RTRIM(pmo.synchro)) WHEN '0' THEN N'-未同步' WHEN '1' THEN N'-已同步' WHEN '2' THEN N'-不同步' ELSE pmo.synchro END | 同步状态
列=CASE UPPER(RTRIM(pmo.dev)) WHEN '1' THEN N'是' WHEN '0' THEN N'否' ELSE pmo.dev END | 研发标识

[映射 salespart_to_salesparts]
字段=salesPartId
关联=ssales | S_SalesParts | ssales.recId = fsto.salesPartId
列=ssales.ifCreateJob | 是否生成同名生产编号
列=ssales.endCustPartNum | 终端产品编号
列=ssales.endCustPartDesc | 终端产品名称
列=ssales.routs | -
列=CASE UPPER(RTRIM(ssales.type)) WHEN 'SAMPLE' THEN N'样板' WHEN 'BATCH' THEN N'批量' WHEN 'OTHER' THEN N'其它' WHEN 'MGSUIT' THEN N'套版主板' WHEN 'SUBSUIT' THEN N'套版子板' WHEN 'MGSUITSAMPLE' THEN N'套板主板样板' WHEN 'SEMIFINISHED' THEN N'半自制' WHEN 'SUBSUITSAMPLE' THEN N'套板子版样版' ELSE ssales.type END | 类型
列=CASE WHEN (UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) = N'有卤') THEN N'有卤' WHEN (UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(ssales.halogenFree AS NVARCHAR(20)))) = N'无卤素') THEN N'无卤素' ELSE CAST(ssales.halogenFree AS NVARCHAR(20)) END | 0有卤
列=CASE WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'建档中') THEN N'建档中' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'待MI') THEN N'待MI' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'2') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'MI制作中') THEN N'MI制作中' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'3') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'退回建档') THEN N'退回建档' WHEN (UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) IN (N'4') OR UPPER(RTRIM(CAST(ssales.archiveStatus AS NVARCHAR(20)))) = N'已完成。') THEN N'已完成。' ELSE CAST(ssales.archiveStatus AS NVARCHAR(20)) END | archiveStatus

