列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifConsignment AS NVARCHAR(20)) END | 是否寄售
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifForeign AS NVARCHAR(20)) END | 是否国外采购商
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifReactionary AS NVARCHAR(20)) END | 是否外协
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifReconcile AS NVARCHAR(20)) END | 是否对账
列=CASE UPPER(RTRIM(ms.status)) WHEN 'VALID' THEN N'审批通过' ELSE ms.status END | 状态

