[表 F_AP_Reconcile]
标签=采购对账
关键词=采购对账
别名=fapr

[映射 sourcetype]
字段=sourceType
类型=枚举
说明=状态码译码：PO 原材料 ，WXPO外协
列=CASE UPPER(RTRIM(fapr.sourceType)) WHEN 'PO' THEN N'原材料' WHEN 'WXPO' THEN N'外协' ELSE fapr.sourceType END | sourceType
禁止=fapr.sourceType AS [sourceType]

[映射 status]
字段=status
类型=枚举
说明=状态码译码：Valid生效Active 活动
列=CASE UPPER(RTRIM(fapr.status)) WHEN 'VALID' THEN N'生效' WHEN 'ACTIVE' THEN N'活动' ELSE fapr.status END | 状态
禁止=fapr.status AS [状态]

[映射 approve_status]
字段=approveStatus
类型=枚举
说明=状态码译码：审批状态：Approved审批通过，Pending制作中
列=CASE UPPER(RTRIM(fapr.approveStatus)) WHEN 'APPROVED' THEN N'审批通过' WHEN 'PENDING' THEN N'制作中' ELSE fapr.approveStatus END | 审批状态
