[表 F_Accounts]
标签=科目管理
关键词=科目管理
别名=facc

[映射 d_c]
字段=d_c
类型=枚举
说明=状态码译码：D:借方   C 贷方
列=CASE UPPER(RTRIM(facc.d_c)) WHEN 'D' THEN N'借方' WHEN 'C' THEN N'贷方' ELSE facc.d_c END | d_c
禁止=facc.d_c AS [d_c]

[映射 type]
字段=type
类型=枚举
说明=状态码译码：类型：Customer 客户  Suppliers 供应商 MaterialGroup 物料分组  ProductGroup 产品分组
列=CASE UPPER(RTRIM(facc.type)) WHEN 'CUSTOMER' THEN N'客户' WHEN 'SUPPLIERS' THEN N'供应商' WHEN 'MATERIALGROUP' THEN N'物料分组' WHEN 'PRODUCTGROUP' THEN N'产品分组' ELSE facc.type END | 类型
禁止=facc.type AS [类型]

[映射 accountgroup_to_accountgroup]
字段=accountGroupId
关联=faccou | F_AccountGroups | faccou.recId = facc.accountGroupId
列=faccou.accountGroupName | 科目分组
列=CASE UPPER(RTRIM(faccou.d_c)) WHEN 'D' THEN N'借贷' WHEN 'C' THEN N'贷方' ELSE faccou.d_c END | d_c

[映射 company]
字段=companyId
关联=tc | T_Company | tc.recId = facc.companyId
列=tc.name | 公司名称
列=tc.code | 公司代码
列=CASE UPPER(RTRIM(tc.postType)) WHEN 'M' THEN N'月度' WHEN 'Y' THEN N'年度' ELSE tc.postType END | 结账方式
列=CASE UPPER(RTRIM(tc.prodType)) WHEN 'SELF' THEN N'自制' WHEN 'INTERNAL' THEN N'内部外发' WHEN 'OUTSOURCING' THEN N'外部外发' ELSE tc.prodType END | 加工方式
列=CASE UPPER(RTRIM(tc.spdsPriceConsignMat)) WHEN 'PO' THEN N'从' WHEN 'SPDS' THEN N'取价' ELSE tc.spdsPriceConsignMat END | spdsPriceConsignMat
列=CASE UPPER(RTRIM(tc.ifMulMICoding)) WHEN 'MI' THEN N'编码' ELSE tc.ifMulMICoding END | ifMulMICoding

[映射 currency_to_currency]
字段=currencyId
关联=tcurre | T_Currency | tcurre.recId = facc.currencyId
列=tcurre.name | 币种名称
列=tcurre.code | 币种代码

[映射 period_to_fiscalperiod]
字段=periodId
关联=tfisca | T_FiscalPeriod | tfisca.recId = facc.periodId
列=tfisca.year | 年度
列=tfisca.ending | 结束日期
列=tfisca.period | 期间
列=tfisca.ifClose | 是否关闭
列=CASE UPPER(RTRIM(tfisca.type)) WHEN 'MONTH' THEN N'月' WHEN 'YEAR' THEN N'年' ELSE tfisca.type END | 类型

[映射 projectcatagory_to_projectcatag]
字段=projectCatagoryId
关联=fproje | F_ProjectCatagory | fproje.recId = facc.projectCatagoryId
列=fproje.name | 名称
列=fproje.seq | 排序
列=fproje.cyb_add_in | -
列=fproje.cyb_add_out | -
