类型=枚举
说明=状态码译码：Pending:制作中   Approved：审批通过
列=CASE UPPER(RTRIM(mbom.approveStatus)) WHEN 'PENDING' THEN N'制作中' WHEN 'APPROVED' THEN N'审批通过' ELSE mbom.approveStatus END | 状态
禁止=mbom.approveStatus AS [状态]

[映射 onhold]
字段=onhold
类型=枚举
说明=枚举译码：关闭   1：关闭  0：激活
列=CASE WHEN (UPPER(RTRIM(CAST(mbom.onhold AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(mbom.onhold AS NVARCHAR(20)))) = N'关闭  0：激活') THEN N'关闭  0：激活' ELSE CAST(mbom.onhold AS NVARCHAR(20)) END | 关闭
禁止=mbom.onhold AS [关闭]

[映射 remaining]
字段=remaining
类型=枚举
说明=枚举译码：回收碎料   1：回收   ，0：不回收
列=CASE WHEN (UPPER(RTRIM(CAST(mbom.remaining AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(mbom.remaining AS NVARCHAR(20)))) = N'回收') THEN N'回收' WHEN (UPPER(RTRIM(CAST(mbom.remaining AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(mbom.remaining AS NVARCHAR(20)))) = N'不回收') THEN N'不回收' ELSE CAST(mbom.remaining AS NVARCHAR(20)) END | 回收碎料   1：回收
