[表 M_IQC]
标签=物料IQC报废
关键词=物料IQC报废
别名=miqc

[映射 approve_status]
字段=approveStatus
类型=枚举
说明=状态码译码：NA 审批通过
列=CASE UPPER(RTRIM(miqc.approveStatus)) WHEN 'NA' THEN N'审批通过' ELSE miqc.approveStatus END | 状态
禁止=miqc.approveStatus AS [状态]

[映射 locked]
字段=locked
类型=枚举
说明=枚举译码：是否审批通过 0否  1是
列=CASE WHEN (UPPER(RTRIM(CAST(miqc.locked AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(miqc.locked AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(miqc.locked AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(miqc.locked AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(miqc.locked AS NVARCHAR(20)) END | 是否审批通过
禁止=miqc.locked AS [是否审批通过]

[映射 status]
字段=status
类型=枚举
说明=状态码译码：单据状态：Valid 有效的
列=CASE UPPER(RTRIM(miqc.status)) WHEN 'VALID' THEN N'有效' ELSE miqc.status END | 单据状态
禁止=miqc.status AS [单据状态]

[映射 type]
字段=type
类型=枚举
说明=状态码译码：Receipt 接收检验  Stock仓库检验
列=CASE UPPER(RTRIM(miqc.type)) WHEN 'RECEIPT' THEN N'接收检验' WHEN 'STOCK' THEN N'仓库检验' ELSE miqc.type END | 类型
禁止=miqc.type AS [类型]

[映射 buyunit_to_unit]
字段=buyUnitId
关联=tunit | T_Unit | tunit.recId = miqc.buyUnitId
列=tunit.name | 单位名称
列=tunit.code | 单位代码

[映射 checkor_to_user]
字段=checkorId
关联=tuser | T_User | tuser.recId = miqc.checkorId
列=tuser.employeeName | 检验员名称
列=tuser.loginName | 检验员账号
列=tuser.userCode | 检验员代码
禁止=miqc.checkorId AS [检验员名称]

[映射 company]
字段=companyId
关联=tc | T_Company | tc.recId = miqc.companyId
列=tc.name | 公司名称
列=tc.code | 公司代码
列=CASE UPPER(RTRIM(tc.postType)) WHEN 'M' THEN N'月度' WHEN 'Y' THEN N'年度' ELSE tc.postType END | 结账方式
列=CASE UPPER(RTRIM(tc.prodType)) WHEN 'SELF' THEN N'自制' WHEN 'INTERNAL' THEN N'内部外发' WHEN 'OUTSOURCING' THEN N'外部外发' ELSE tc.prodType END | 加工方式
列=CASE UPPER(RTRIM(tc.spdsPriceConsignMat)) WHEN 'PO' THEN N'从' WHEN 'SPDS' THEN N'取价' ELSE tc.spdsPriceConsignMat END | spdsPriceConsignMat
列=CASE UPPER(RTRIM(tc.ifMulMICoding)) WHEN 'MI' THEN N'编码' ELSE tc.ifMulMICoding END | ifMulMICoding

[映射 creator]
字段=creatorId
关联=tu | T_User | tu.recId = miqc.creatorId
列=tu.employeeName | 创建人名称
列=tu.loginName | 创建人账号
列=tu.userCode | 创建人代码
禁止=miqc.creatorId AS [创建人名称]

[映射 flowtype_to_flowtype]
