关联=tp | T_Plants | tp.recId = miqc.plantsId
列=tp.name | 工厂名称
列=tp.code | 工厂代码
列=CASE UPPER(RTRIM(tp.ifPanelBOtherMI)) WHEN 'AB' THEN N'板允许' WHEN 'B' THEN N'板换料号' ELSE tp.ifPanelBOtherMI END | ifPanelBOtherMI

[映射 post_role]
字段=postRoleId
关联=tpostr | T_PostRole | tpostr.recId = miqc.postRoleId
