列=tdefec.sort | 排序
列=CASE WHEN (UPPER(RTRIM(CAST(tdefec.ifActive AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(tdefec.ifActive AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(tdefec.ifActive AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(tdefec.ifActive AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(tdefec.ifActive AS NVARCHAR(20)) END | 是否激活
列=CASE WHEN (UPPER(RTRIM(CAST(tdefec.ifMaterials AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(tdefec.ifMaterials AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(tdefec.ifMaterials AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(tdefec.ifMaterials AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(tdefec.ifMaterials AS NVARCHAR(20)) END | 是否用于物料
列=CASE WHEN (UPPER(RTRIM(CAST(tdefec.ifProduct AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(tdefec.ifProduct AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(tdefec.ifProduct AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(tdefec.ifProduct AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(tdefec.ifProduct AS NVARCHAR(20)) END | 是否用于成品
列=CASE WHEN (UPPER(RTRIM(CAST(tdefec.ifWIP AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(tdefec.ifWIP AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(tdefec.ifWIP AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(tdefec.ifWIP AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(tdefec.ifWIP AS NVARCHAR(20)) END | ifWIP
列=CASE UPPER(RTRIM(tdefec.type)) WHEN 'REPAIR' THEN N'返修' WHEN 'RETURN' THEN N'退货' WHEN 'DEFECT' THEN N'特采' WHEN 'SCRAPPED' THEN N'报废' ELSE tdefec.type END | 类型
列=CASE WHEN (UPPER(RTRIM(CAST(tdefec.ifSpecial AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(tdefec.ifSpecial AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(tdefec.ifSpecial AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(tdefec.ifSpecial AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(tdefec.ifSpecial AS NVARCHAR(20)) END | 是否用于特定

