[表 M_Receipt]
标签=物料接收
关键词=物料接收, 收货单
别名=mrec

[映射 type]
字段=type
类型=枚举
说明=状态码译码：PO 有采购接收 NPO无采购接收 MiscPO 杂项采购接收
列=CASE UPPER(RTRIM(mrec.type)) WHEN 'PO' THEN N'有采购接收' WHEN 'NPO' THEN N'无采购接收' WHEN 'MISCPO' THEN N'杂项采购接收' WHEN 'C' THEN N'寄售接收' ELSE mrec.type END | 接收类型
禁止=mrec.type AS [接收类型]

[映射 company]
字段=companyId
关联=tc | T_Company | tc.recId = mrec.companyId
列=tc.name | 公司名称
列=tc.code | 公司代码
列=CASE UPPER(RTRIM(tc.postType)) WHEN 'M' THEN N'月度' WHEN 'Y' THEN N'年度' ELSE tc.postType END | 结账方式
列=CASE UPPER(RTRIM(tc.prodType)) WHEN 'SELF' THEN N'自制' WHEN 'INTERNAL' THEN N'内部外发' WHEN 'OUTSOURCING' THEN N'外部外发' ELSE tc.prodType END | 加工方式
列=CASE UPPER(RTRIM(tc.spdsPriceConsignMat)) WHEN 'PO' THEN N'从' WHEN 'SPDS' THEN N'取价' ELSE tc.spdsPriceConsignMat END | spdsPriceConsignMat
列=CASE UPPER(RTRIM(tc.ifMulMICoding)) WHEN 'MI' THEN N'编码' ELSE tc.ifMulMICoding END | ifMulMICoding

[映射 creator]
字段=creatorId
关联=tu | T_User | tu.recId = mrec.creatorId
列=tu.employeeName | 创建人名称
列=tu.loginName | 创建人账号
列=tu.userCode | 创建人代码
禁止=mrec.creatorId AS [创建人名称]

[映射 plants]
字段=plantsId
关联=tp | T_Plants | tp.recId = mrec.plantsId
列=tp.name | 工厂名称
列=tp.code | 工厂代码
列=CASE UPPER(RTRIM(tp.ifPanelBOtherMI)) WHEN 'AB' THEN N'板允许' WHEN 'B' THEN N'板换料号' ELSE tp.ifPanelBOtherMI END | ifPanelBOtherMI

[映射 post_role]
字段=postRoleId
关联=tpostr | T_PostRole | tpostr.recId = mrec.postRoleId
列=tpostr.name | 岗位名称
列=tpostr.code | 岗位代码
列=CASE UPPER(RTRIM(tpostr.type)) WHEN 'GENERAL' THEN N'一般类型' WHEN 'MI' THEN N'工程设计' ELSE tpostr.type END | 岗位类型

[映射 supplier]
字段=suppliersId
关联=ms | M_Suppliers | ms.recId = mrec.suppliersId
列=ms.name | 供应商名称
列=ms.code | 供应商代码
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifActive AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifActive AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifActive AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifActive AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifActive AS NVARCHAR(20)) END | 是否激活
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifConsignment AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifConsignment AS NVARCHAR(20)) END | 是否寄售
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifForeign AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifForeign AS NVARCHAR(20)) END | 是否国外采购商
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifReactionary AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifReactionary AS NVARCHAR(20)) END | 是否外协
列=CASE WHEN (UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(ms.ifReconcile AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(ms.ifReconcile AS NVARCHAR(20)) END | 是否对账
列=CASE UPPER(RTRIM(ms.status)) WHEN 'VALID' THEN N'审批通过' ELSE ms.status END | 状态

