列=CASE WHEN (UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sjob.soOnhold AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sjob.soOnhold AS NVARCHAR(20)) END | 销售暂停；0: 否
列=CASE WHEN (UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(sjob.halogenFree AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(sjob.halogenFree AS NVARCHAR(20)) END | 无卤素；0: 否
