[映射 moroute_to_moroute]
字段=moRouteId
关联=pmorou | P_MORoute | pmorou.recId = sosw.moRouteId
列=pmorou.cr | -
列=pmorou.inTime | -
列=pmorou.outTime | -
列=pmorou.planSeq | -
列=CASE WHEN (UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) = N'是') THEN N'打勾' WHEN (UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) = N'否') THEN N'不打勾' ELSE CAST(pmorou.step_HOLD AS NVARCHAR(20)) END | 外协暂停
列=CASE WHEN (UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)) END | 是否需要过数

[映射 wo]
字段=woId
关联=pwo | P_WO | pwo.recId = sosw.woId
列=CASE UPPER(RTRIM(pwo.ab)) WHEN 'A' THEN N'A板' WHEN 'B' THEN N'B板' WHEN 'A' THEN N'A板' ELSE pwo.ab END | ab
列=CASE WHEN (UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) = N'外协') THEN N'外协' WHEN (UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) IN (N'2') OR UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) = N'未发放') THEN N'未发放' WHEN (UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) IN (N'3') OR UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) = N'已发放') THEN N'已发放' WHEN (UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) IN (N'4') OR UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) = N'暂停') THEN N'暂停' WHEN (UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) IN (N'5') OR UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) = N'取消') THEN N'取消' WHEN (UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) IN (N'6') OR UPPER(RTRIM(CAST(pwo.status AS NVARCHAR(20)))) = N'完成') THEN N'完成' ELSE CAST(pwo.status AS NVARCHAR(20)) END | 工单状态

