[映射 approve_status]
字段=approveStatus
类型=枚举
说明=状态码译码：审批状态：Pending 制作中 Waiting 审核中 Approved 审核通过
列=CASE UPPER(RTRIM(sosp.approveStatus)) WHEN 'PENDING' THEN N'制作中' WHEN 'WAITING' THEN N'审核中' WHEN 'APPROVED' THEN N'审核通过' ELSE sosp.approveStatus END | 审批状态
禁止=sosp.approveStatus AS [审批状态]

[映射 status]
字段=status
类型=枚举
说明=状态码译码：单据状态：Active 制作中 Valid 生效(审批通过)，Onhold 暂缓 Cancel 取消 Close 关闭 Void 失效
列=CASE UPPER(RTRIM(sosp.status)) WHEN 'ACTIVE' THEN N'制作中' WHEN 'VALID' THEN N'生效(审批通过)' WHEN 'ONHOLD' THEN N'暂缓' WHEN 'CANCEL' THEN N'取消' WHEN 'CLOSE' THEN N'关闭' WHEN 'VOID' THEN N'失效' ELSE sosp.status END | 单据状态
