[映射 halogenfree]
字段=halogenFree
类型=枚举
说明=枚举译码：0有卤，1无卤素
列=CASE WHEN (UPPER(RTRIM(CAST(ssal.halogenFree AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(ssal.halogenFree AS NVARCHAR(20)))) = N'有卤') THEN N'有卤' WHEN (UPPER(RTRIM(CAST(ssal.halogenFree AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(ssal.halogenFree AS NVARCHAR(20)))) = N'无卤素') THEN N'无卤素' ELSE CAST(ssal.halogenFree AS NVARCHAR(20)) END | 0有卤
禁止=ssal.halogenFree AS [0有卤]

[映射 archivestatus]
字段=archiveStatus
类型=枚举
说明=枚举译码：0:建档中 ;1:待MI;2:MI制作中；3：退回建档 ；4：已完成。
