[表 T_Defect]
标签=缺陷表
关键词=缺陷表
别名=tdef

[映射 ifactive]
字段=ifActive
类型=枚举
说明=枚举译码：是否激活 0否  1是
列=CASE WHEN (UPPER(RTRIM(CAST(tdef.ifActive AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(tdef.ifActive AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(tdef.ifActive AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(tdef.ifActive AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(tdef.ifActive AS NVARCHAR(20)) END | 是否激活
禁止=tdef.ifActive AS [是否激活]

[映射 ifmaterials]
字段=ifMaterials
类型=枚举
说明=枚举译码：是否用于物料 0否  1是
列=CASE WHEN (UPPER(RTRIM(CAST(tdef.ifMaterials AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(tdef.ifMaterials AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(tdef.ifMaterials AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(tdef.ifMaterials AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(tdef.ifMaterials AS NVARCHAR(20)) END | 是否用于物料
禁止=tdef.ifMaterials AS [是否用于物料]

[映射 ifproduct]
