[表 W_WIPStepDetails]
标签=W_WIPStepDetails
关键词=W_WIPStepDetails
别名=wwip

[映射 ifnew]
字段=ifNew
类型=枚举
说明=枚举译码：是否新单 0 否 1 是
列=CASE WHEN (UPPER(RTRIM(CAST(wwip.ifNew AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(wwip.ifNew AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(wwip.ifNew AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(wwip.ifNew AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(wwip.ifNew AS NVARCHAR(20)) END | 是否新单
禁止=wwip.ifNew AS [是否新单]

[映射 ifforecast]
字段=ifForecast
类型=枚举
说明=枚举译码：是否预测（0：正常，1：预测）
列=CASE WHEN (UPPER(RTRIM(CAST(wwip.ifForecast AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(wwip.ifForecast AS NVARCHAR(20)))) = N'正常') THEN N'正常' WHEN (UPPER(RTRIM(CAST(wwip.ifForecast AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(wwip.ifForecast AS NVARCHAR(20)))) = N'预测') THEN N'预测' ELSE CAST(wwip.ifForecast AS NVARCHAR(20)) END | ifForecast
禁止=wwip.ifForecast AS [ifForecast]

[映射 non_planned]
字段=non_Planned
类型=枚举
说明=枚举译码：不投产订单 1是 0否
列=CASE WHEN (UPPER(RTRIM(CAST(wwip.non_Planned AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(wwip.non_Planned AS NVARCHAR(20)))) = N'是') THEN N'是' WHEN (UPPER(RTRIM(CAST(wwip.non_Planned AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(wwip.non_Planned AS NVARCHAR(20)))) = N'否') THEN N'否' ELSE CAST(wwip.non_Planned AS NVARCHAR(20)) END | 不投产订单
禁止=wwip.non_Planned AS [不投产订单]

[映射 backlogunit_to_unit]
字段=backlogUnitId
关联=tunit | T_Unit | tunit.recId = wwip.backlogUnitId
列=tunit.name | 单位名称
列=tunit.code | 单位代码

[映射 iqc_to_iqc]
字段=iqcId
关联=fgiiqc | FGI_IQC | fgiiqc.recId = wwip.iqcId
列=fgiiqc.code | 检验单号
列=fgiiqc.moId | 制造单号，对应P_MO.recId
列=fgiiqc.sourceCode | 外协采购单号
列=fgiiqc.deliveryCode | 送货/送检单号
列=CASE WHEN (UPPER(RTRIM(CAST(fgiiqc.ifOutPut AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(fgiiqc.ifOutPut AS NVARCHAR(20)))) = N'禁用') THEN N'禁用' WHEN (UPPER(RTRIM(CAST(fgiiqc.ifOutPut AS NVARCHAR(20)))) IN (N'1') OR UPPER(RTRIM(CAST(fgiiqc.ifOutPut AS NVARCHAR(20)))) = N'启用') THEN N'启用' ELSE CAST(fgiiqc.ifOutPut AS NVARCHAR(20)) END | 合格入库状态
列=CASE WHEN (UPPER(RTRIM(CAST(fgiiqc.ifStock AS NVARCHAR(20)))) IN (N'0') OR UPPER(RTRIM(CAST(fgiiqc.ifStock AS NVARCHAR(20)))) = N'.未入库   1.已入库') THEN N'.未入库   1.已入库' ELSE CAST(fgiiqc.ifStock AS NVARCHAR(20)) END | 入库状态
列=CASE UPPER(RTRIM(fgiiqc.status)) WHEN 'VALID' THEN N'生效' ELSE fgiiqc.status END | 单据状态
列=CASE UPPER(RTRIM(fgiiqc.type)) WHEN 'STOCK' THEN N'仓库' WHEN 'RECEIPT' THEN N'客诉' ELSE fgiiqc.type END | 类型
列=CASE UPPER(RTRIM(fgiiqc.woType)) WHEN 'UNWORKING' THEN N'未加工' WHEN 'WORKING' THEN N'已加工' ELSE fgiiqc.woType END | 工单状态

[映射 nextoutputmoroute_to_moroute]
字段=nextOutputMORouteId
关联=pmorou | P_MORoute | pmorou.recId = wwip.nextOutputMORouteId
列=pmorou.cr | -
列=pmorou.inTime | -
列=pmorou.outTime | -
列=pmorou.planSeq | -
列=CASE WHEN (UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) = N'是') THEN N'打勾' WHEN (UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(pmorou.step_HOLD AS NVARCHAR(20)))) = N'否') THEN N'不打勾' ELSE CAST(pmorou.step_HOLD AS NVARCHAR(20)) END | 外协暂停
列=CASE WHEN (UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) IN (N'0', N'FALSE', N'N', N'NO') OR UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) = N'否') THEN N'否' WHEN (UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) IN (N'1', N'TRUE', N'Y', N'YES') OR UPPER(RTRIM(CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)))) = N'是') THEN N'是' ELSE CAST(pmorou.ifBarcodEntry AS NVARCHAR(20)) END | 是否需要过数

